html:
{%- set c = dgi_invoice_context(doc) -%}
{%- set ccy = c.totals.currency -%}
{%- macro m(v, cur=None) -%}{{ frappe.utils.fmt_money(v or 0, currency=(cur or ccy)) }}{%- endmacro -%}
{%- macro q(v) -%}{{ ("%.3f"|format(v or 0)).rstrip("0").rstrip(".") }}{%- endmacro -%}
<div class="fn">
<style>
  .fn{font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#1b1b1b;line-height:1.3;}
  .fn table{border-collapse:collapse;width:100%;}
  .fn td,.fn th{vertical-align:top;}
  .fn .kv td{padding:1px 4px 1px 0;}
  .fn .kv td.k{color:#5a5a5a;white-space:nowrap;padding-right:10px;width:1%;}
  .fn .co-name{font-size:18px;font-weight:bold;color:#12355b;margin-bottom:2px;}
  .fn .title{font-size:21px;font-weight:bold;color:#12355b;text-align:right;letter-spacing:.3px;}
  .fn .title-sub{text-align:right;font-size:11.5px;}
  .fn .tag{display:inline-block;border:1px solid #12355b;color:#12355b;padding:1px 7px;border-radius:2px;font-weight:bold;font-size:11px;}
  .fn .tag-red{border-color:#a3171b;color:#a3171b;}
  .fn .box{border:1px solid #c9d3df;border-radius:3px;padding:5px 7px;}
  .fn .box-pos{border:1.5px solid #1b8fb5;}
  .fn h4{margin:0 0 4px 0;font-size:11.5px;color:#12355b;border-bottom:1px solid #12355b;padding-bottom:2px;text-transform:uppercase;letter-spacing:.3px;}
  .fn .items th{background:#12355b;color:#fff;font-size:9.5px;font-weight:bold;padding:4px 3px;border:1px solid #12355b;text-align:right;}
  .fn .items td{padding:3px;border:1px solid #d5dbe3;text-align:right;font-size:10px;}
  .fn .items .l{text-align:left;}
  .fn .items .c{text-align:center;}
  .fn .items tr.alt td{background:#f5f8fb;}
  .fn .items td.ts{color:#5a5a5a;font-style:italic;border-top:none;}
  .fn .grid th{background:#eef2f7;border:1px solid #d5dbe3;padding:3px;font-size:9.5px;text-align:right;}
  .fn .grid td{border:1px solid #d5dbe3;padding:2px 4px;text-align:right;font-size:10px;}
  .fn .grid .l{text-align:left;}
  .fn .tot td{padding:2px 4px;}
  .fn .tot td.k{text-align:right;color:#333;}
  .fn .tot td.v{text-align:right;white-space:nowrap;min-width:95px;}
  .fn .tot tr.net td{font-size:13px;font-weight:bold;border-top:2px solid #12355b;color:#12355b;padding-top:4px;}
  .fn .cdf{margin-top:4px;background:#f2f6fa;border:1px solid #12355b;border-radius:3px;padding:4px 6px;}
  .fn .cdf td{padding:1px 2px;}
  .fn .words{margin-top:5px;font-style:italic;font-weight:bold;color:#222;}
  .fn .banner{background:#fdecec;border:1px solid #d99;color:#a3171b;padding:5px;text-align:center;font-weight:bold;border-radius:3px;margin:6px 0;}
  .fn .sec td.k{font-weight:bold;color:#12355b;}
  .fn .muted{color:#777;}
  .fn .foot{margin-top:6px;font-size:8.5px;color:#888;text-align:center;}
</style>

<!-- ============ EN-TETE ============ -->
<table><tr>
  <td style="width:58%;">
    {% if c.company.logo %}<img src="{{ c.company.logo }}" style="max-height:48px;max-width:170px;margin-bottom:4px;">{% endif %}
    <div class="co-name">{{ c.company.name|e }}</div>
    {% for ln in c.company.address %}<div>{{ ln|e }}</div>{% endfor %}
    <table class="kv" style="margin-top:4px;width:auto;">
      {% if c.company.email %}<tr><td class="k">E-mail</td><td>{{ c.company.email|e }}</td></tr>{% endif %}
      {% if c.company.phone %}<tr><td class="k">Numéro contact</td><td>{{ c.company.phone|e }}</td></tr>{% endif %}
      <tr><td class="k">Numéro impôt (NIF)</td><td><b>{{ c.company.nif|e }}</b></td></tr>
      {% if c.company.rccm %}<tr><td class="k">RCCM</td><td>{{ c.company.rccm|e }}</td></tr>{% endif %}
      {% if c.company.id_nat %}<tr><td class="k">Id. Nat.</td><td>{{ c.company.id_nat|e }}</td></tr>{% endif %}
      <tr><td class="k">Référence ISF</td><td><b>{{ c.company.isf|e }}</b></td></tr>
    </table>
  </td>
  <td style="width:42%;">
    <div class="title">{{ c.title }}</div>
    {% if c.export %}<div class="title-sub"><span class="tag">{{ c.export }}</span></div>{% endif %}
    <div class="title-sub" style="margin-top:3px;font-size:11px;"><b>N° {{ c.general.number }}</b></div>
    <div class="title-sub" style="margin-top:3px;">
      <span class="tag {% if c.copy_label == 'DUPLICATA' %}tag-red{% endif %}">{{ c.copy_label }}</span>
    </div>
    <div class="title-sub muted" style="margin-top:3px;">Type DGI : <b>{{ c.invoice_type }}</b> – {{ c.invoice_type_label|e }}</div>
    {% if c.credit %}<div class="title-sub" style="margin-top:2px;color:#a3171b;"><b>{{ c.credit.nature_label or "Nature non précisée" }}</b></div>{% endif %}
  </td>
</tr></table>

{% if not c.normalized %}
<div class="banner">DOCUMENT NON NORMALISÉ – ne vaut pas facture (en attente des éléments de sécurité DGI)</div>
{% endif %}

<!-- ============ CLIENT / POINT DE VENTE ============ -->
<table style="margin-top:7px;"><tr>
  <td style="width:55%;padding-right:6px;">
    <div class="box"><h4>Information client</h4>
      <table class="kv">
        <tr><td class="k">Code client</td><td>{{ c.client.code|e }}</td></tr>
        <tr><td class="k">Nom du client</td><td><b>{{ c.client.name|e }}</b></td></tr>
        {% if c.client.address %}<tr><td class="k">Adresse</td><td>{% for ln in c.client.address %}{{ ln|e }}{% if not loop.last %}<br>{% endif %}{% endfor %}</td></tr>{% endif %}
        {% if c.client.city %}<tr><td class="k">Ville</td><td>{{ c.client.city|e }}</td></tr>{% endif %}
        {% if c.client.country %}<tr><td class="k">Pays</td><td>{{ c.client.country|e }}</td></tr>{% endif %}
        <tr><td class="k">Type de client</td><td>{{ c.client.type_label|e }}</td></tr>
        {% if c.client.contact %}<tr><td class="k">Contact</td><td>{{ c.client.contact|e }}</td></tr>{% endif %}
        {% if c.client.phone %}<tr><td class="k">Numéro contact</td><td>{{ c.client.phone|e }}</td></tr>{% endif %}
        {% if c.client.email %}<tr><td class="k">E-mail</td><td>{{ c.client.email|e }}</td></tr>{% endif %}
        <tr><td class="k">Numéro impôt (NIF)</td><td>{{ c.client.nif|e }}</td></tr>
        {% if c.client.registration %}<tr><td class="k">N° d'enregistrement</td><td>{{ c.client.registration|e }}</td></tr>{% endif %}
      </table>
    </div>
  </td>
  <td style="width:45%;padding-left:6px;">
    <div class="box box-pos"><h4>Point de vente</h4>
      <table class="kv">
        <tr><td class="k">Code magasin</td><td><b>{{ c.pos.code|e }}</b></td></tr>
        {% if c.pos.name %}<tr><td class="k">Nom</td><td>{{ c.pos.name|e }}</td></tr>{% endif %}
        <tr><td class="k">Adresse</td><td>{{ c.pos.address|e }}</td></tr>
        <tr><td class="k">Ville</td><td>{{ c.pos.city|e }}</td></tr>
        {% if c.pos.phone %}<tr><td class="k">Téléphone</td><td>{{ c.pos.phone|e }}</td></tr>{% endif %}
        <tr><td class="k">Référence NID</td><td>{{ c.pos.nid|e }}</td></tr>
        {% if c.pos.terminal %}<tr><td class="k">Terminal / caisse</td><td>{{ c.pos.terminal|e }}</td></tr>{% endif %}
      </table>
    </div>
  </td>
</tr></table>

<!-- ============ INFORMATIONS GENERALES ============ -->
<div class="box" style="margin-top:7px;"><h4>Informations générales</h4>
  <table><tr>
    <td style="width:50%;">
      <table class="kv">
        <tr><td class="k">Facture N°</td><td><b>{{ c.general.number }}</b></td></tr>
        {% if c.general.orders %}<tr><td class="k">Commande N°</td><td>{{ c.general.orders|e }}</td></tr>{% endif %}
        <tr><td class="k">Date et heure</td><td>{{ c.general.date }} {{ c.general.time }}</td></tr>
        {% if c.general.due_date %}<tr><td class="k">Échéance</td><td>{{ c.general.due_date }}</td></tr>{% endif %}
        <tr><td class="k">Terme de paiement</td><td>{{ c.general.payment_terms|e }}</td></tr>
        <tr><td class="k">Mode de paiement</td><td><b>{{ c.general.payment_modes|e }}</b></td></tr>
      </table>
    </td>
    <td style="width:50%;">
      <table class="kv">
        <tr><td class="k">Type de facture DGI</td><td><b>{{ c.invoice_type }}</b> – {{ c.invoice_type_label|e }}</td></tr>
        <tr><td class="k">Devise</td><td>{{ ccy }}{% if c.foreign %} (1 {{ ccy }} = {{ c.cur_rate_txt }} CDF){% endif %} – prix {{ c.general.price_mode }}</td></tr>
        <tr><td class="k">Point de vente</td><td>{{ c.pos.code|e }}{% if c.pos.name %} – {{ c.pos.name|e }}{% endif %}</td></tr>
        <tr><td class="k">Utilisateur</td><td>{{ c.general.operator_name|e }} <span class="muted">({{ c.general.operator_id|e }})</span></td></tr>
        <tr><td class="k">Date de création</td><td>{{ c.general.created }}</td></tr>
        <tr><td class="k">Version</td><td>{{ c.copy_label }}</td></tr>
      </table>
    </td>
  </tr></table>
</div>

{% if c.credit %}
<div class="box" style="margin-top:7px;border-color:#a3171b;"><h4 style="color:#a3171b;border-color:#a3171b;">Facture d'avoir</h4>
  <table class="kv">
    <tr><td class="k">Nature de l'avoir</td><td><b>{{ c.credit.nature }} – {{ c.credit.nature_label }}</b></td></tr>
    <tr><td class="k">Référence facture d'origine (Code DEF/DGI)</td><td><b>{{ c.credit.reference|e }}</b></td></tr>
    {% if c.credit.original %}<tr><td class="k">Facture d'origine</td><td>{{ c.credit.original|e }}</td></tr>{% endif %}
  </table>
</div>
{% endif %}

<!-- ============ ARTICLES ============ -->
<table class="items" style="margin-top:8px;">
  <thead><tr>
    <th class="c" style="width:3%;">#</th>
    <th class="l" style="width:11%;">Code article</th>
    <th class="l">Désignation</th>
    <th class="c" style="width:5%;">Type</th>
    <th style="width:6%;">Qté</th>
    <th class="l" style="width:5%;">UM</th>
    <th style="width:11%;">P.U. {{ c.general.price_mode }}</th>
    <th style="width:9%;">Remise</th>
    <th style="width:12%;">Montant {{ c.general.price_mode }}</th>
    <th class="c" style="width:5%;">Groupe</th>
    <th style="width:5%;">TVA %</th>
  </tr></thead>
  <tbody>
  {% for r in c.lines %}
    <tr class="{{ 'alt' if loop.index % 2 == 0 else '' }}">
      <td class="c">{{ loop.index }}</td>
      <td class="l">{{ r.code|e }}</td>
      <td class="l">{{ r.name|e }}{% if r.discount_label %} <span class="muted">({{ r.discount_label }})</span>{% endif %}</td>
      <td class="c">[{{ r.type }}]</td>
      <td>{{ q(r.qty) }}</td>
      <td class="l">{{ r.uom|e }}</td>
      <td>{{ m(r.unit_price) }}</td>
      <td>{{ m(r.discount) if r.discount else "" }}</td>
      <td>{{ m(r.amount) }}</td>
      <td class="c"><b>{{ r.group_label }}</b></td>
      <td>{% if r.rate is not none %}{{ "%g"|format(r.rate) }}{% endif %}</td>
    </tr>
    {% if r.ts_amount %}
    <tr class="{{ 'alt' if loop.index % 2 == 0 else '' }}"><td></td><td></td>
      <td class="l ts" colspan="6">T.S. – Taxe spécifique {{ r.ts_label }} (incluse)</td>
      <td class="ts">{{ m(r.ts_amount) }}</td><td></td><td></td></tr>
    {% endif %}
  {% endfor %}
  </tbody>
</table>

<!-- ============ TAXES / PAIEMENTS / TOTAUX ============ -->
<table style="margin-top:8px;"><tr>
  <td style="width:56%;padding-right:10px;">
    <h4>Ventilation par groupe de taxation{% if not c.foreign %} (CDF){% endif %}</h4>
    <table class="grid">
      <thead><tr><th class="l">Groupe</th><th>Taux</th><th>Total H.T.</th><th>Total TVA</th><th>Total T.T.C.</th></tr></thead>
      <tbody>
      {% for g in c.totals.table %}
        <tr><td class="l"><b>[{{ g.label }}]</b></td><td>{{ "%g"|format(g.rate or 0) }} %</td>
            <td>{{ m(g.ht) }}</td><td>{{ m(g.vat) }}</td><td>{{ m(g.total) }}</td></tr>
      {% endfor %}
      </tbody>
    </table>

    <h4 style="margin-top:8px;">Règlement</h4>
    <table class="grid">
      <thead><tr><th class="l">Mode de paiement</th><th class="l">Type DGI</th><th>Montant</th></tr></thead>
      <tbody>
      {% for p in c.payments %}
        <tr><td class="l">{{ p.label|e }}</td><td class="l">{{ p.type|default("") }}</td><td>{{ m(p.amount) }}</td></tr>
      {% endfor %}
      </tbody>
    </table>
    <div style="margin-top:4px;">Nombre d'articles : <b>{{ c.item_count }}</b></div>
  </td>
  <td style="width:44%;">
    <table class="tot">
      {% if c.totals.discount %}
      <tr><td class="k">Montant brut</td><td class="v">{{ m(c.totals.gross) }}</td></tr>
      <tr><td class="k">Remises</td><td class="v">- {{ m(c.totals.discount) }}</td></tr>
      {% endif %}
      <tr><td class="k">Total H.T.</td><td class="v">{{ m(c.totals.ht) }}</td></tr>
      {% if c.totals.ts %}<tr><td class="k">Taxe spécifique</td><td class="v">{{ m(c.totals.ts) }}</td></tr>{% endif %}
      <tr><td class="k">Total TVA</td><td class="v">{{ m(c.totals.vat) }}</td></tr>
      <tr class="net"><td class="k">Net à payer T.T.C. ({{ ccy }})</td><td class="v">{{ m(c.totals.ttc) }}</td></tr>
      {% if c.totals.rounded %}<tr><td class="k muted">Montant arrondi à payer</td><td class="v">{{ m(c.totals.rounded) }}</td></tr>{% endif %}
    </table>
    {% if c.foreign %}
    <div class="cdf">
      <table class="tot">
        <tr><td class="k" colspan="2" style="text-align:left;color:#12355b;"><b>Équivalent en Francs Congolais</b> <span class="muted">(taux de la facture : 1 {{ ccy }} = {{ c.cur_rate_txt }} CDF)</span></td></tr>
        <tr><td class="k">Total H.T. (CDF)</td><td class="v">{{ m(c.cdf.ht, "CDF") }}</td></tr>
        <tr><td class="k">Total TVA (CDF)</td><td class="v">{{ m(c.cdf.vat, "CDF") }}</td></tr>
        <tr><td class="k"><b>Net à payer T.T.C. (CDF)</b></td><td class="v"><b>{{ m(c.cdf.ttc, "CDF") }}</b></td></tr>
      </table>
    </div>
    {% endif %}
    <div class="words">Arrêtée la présente facture à la somme de : {{ c.amount_in_words }}.</div>
  </td>
</tr></table>

{% if c.comments %}
<div class="box" style="margin-top:7px;"><h4>Commentaires</h4>
  <table class="kv">{% for cm in c.comments %}<tr><td class="k">{{ cm.label }}</td><td>{{ cm.value|e }}</td></tr>{% endfor %}</table>
</div>
{% endif %}

<!-- ============ ELEMENTS DE SECURITE ============ -->
<div class="box" style="margin-top:8px;">
<table class="sec"><tr>
  <td style="width:140px;text-align:center;vertical-align:middle;">
    {% if c.security.qr_image %}<img src="{{ c.security.qr_image }}" style="width:130px;height:130px;" alt="QR DGI">
    {% else %}<div style="width:130px;height:130px;border:1px dashed #bbb;color:#aaa;line-height:130px;margin:auto;">QR</div>{% endif %}
  </td>
  <td style="padding-left:10px;vertical-align:middle;">
    <table class="kv">
      <tr><td class="k">CODE DEF/DGI</td><td style="font-size:13px;"><b>{{ c.security.code_def or "NON NORMALISÉE" }}</b></td></tr>
      <tr><td class="k">DEF NID</td><td>{{ c.security.nim }}</td></tr>
      <tr><td class="k">DEF Compteurs</td><td>{{ c.security.counters }}</td></tr>
      <tr><td class="k">DEF Heure</td><td>{{ c.security.datetime }}</td></tr>
    </table>
    <div class="muted" style="margin-top:4px;">Facture normalisée – éléments de sécurité délivrés par l'e-MCF de la DGI. Scannez le code QR pour vérifier son authenticité.</div>
  </td>
</tr></table>
</div>

<div class="foot">{{ c.company.name|e }} – NIF {{ c.company.nif|e }} – ISF {{ c.company.isf|e }} – ERPNext / DGI Compliance v{{ c.app_version }}</div>
</div>
